                )

    if _data is None or _schema is None:
        raise Exception(f"Invalid data for value type 'list': {data}")

    result = {
        "list_data": _data,
        "item_schema": _schema,
        "python_class": PythonClass.from_class(python_cls).model_dump(),
    }

    result_model = KiaraList(**result)
    return result_model
